// Assess each client row and route to remind / escalate / all clear.
const rows = $input.all().map(i => i.json);
const firm = $('Set Firm Chase Settings').first().json;
const now = new Date();
function daysSince(dateStr){
  if(!dateStr) return Infinity;
  const d = new Date(String(dateStr));
  if(isNaN(d.getTime())) return Infinity;
  return Math.floor((now.getTime() - d.getTime()) / 86400000);
}
const split = (s) => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
const lower = (s) => String(s || '').trim().toLowerCase();
const actions = [];
let anyMissing = false;
for (const i of rows){
  const f = i.fields || i;
  const required = split(f.required_docs);
  const received = split(f.received_docs);
  const recvLow = received.map(lower);
  const missing = required.filter(d => !recvLow.includes(lower(d)));
  if (missing.length > 0){ anyMissing = true; }
  const age = daysSince(f.last_reminded);
  let action = 'none';
  if (missing.length > 0){
    if (!f.last_reminded){ action = 'remind'; }
    else if (age >= 7){ action = 'escalate'; }
    else if (age >= 3){ action = 'remind'; }
    else { action = 'none'; }
  }
  if (action !== 'none'){
    actions.push({
      client_id: String(f.client_id || ''), client_name: String(f.client_name || ''),
      email: String(f.email || ''), required_docs: f.required_docs,
      received_docs: f.received_docs, missing_docs: missing,
      missing_text: missing.join(', '), missing_count: missing.length,
      days_since: (age === Infinity ? null : age),
      action, firm_name: firm.firm_name, owner_email: firm.owner_email
    });
  }
}
if (actions.length > 0){ return actions.map(a => ({ json: a })); }
if (anyMissing){ return []; } // clients still missing docs but nothing due today: stay quiet
return [{ json: { action: 'all-clear', firm_name: firm.firm_name } }];

// Parse the AI reminder draft. Falls back to a deterministic reminder.
const it = $input.first().json;
let raw = String(it.output != null ? it.output : '').trim();
raw = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let p = {};
const m = raw.match(/\{[\s\S]*\}/);
if (m){ try { p = JSON.parse(m[0]); } catch(e){ try { p = JSON.parse(m[0].replace(/'/g,'"')); } catch(e2){} } }
const ctx0 = it;
let ctx = ctx0;
try { ctx = $('Evaluate Client Status').item.json || ctx0; } catch(e) { ctx = ctx0; }
const fallbackSubj = 'Reminder: ' + ctx.missing_text + ' still needed for your return';
const fallbackBody = 'Hi ' + ctx.client_name + ',\n\nWe are still waiting on: ' + ctx.missing_text + '.\n\nPlease send these as soon as you can so we can finish your return.\n\n' + ctx.firm_name;
const clean = (s) => String(s).replace(/[\u2014\u2013]/g, '-');
return [{ json: {
  client_id: ctx.client_id, client_name: ctx.client_name, client_email: ctx.email,
  subject: clean(p.subject || fallbackSubj), body: clean(p.body || fallbackBody),
  firm_name: ctx.firm_name
} }];

// Match the intake client_id against the Clients table and prepare the receipt.
const rows = $input.all().map(i => i.json);
const ctx = $('Set Intake Data').first().json;
const cid = String(ctx.client_id || '').trim().toUpperCase();
const doc = String(ctx.doc || '').trim();
const split = (s) => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
const lower = (s) => String(s || '').trim().toLowerCase();
const rec = rows.map(r => r.fields || r).find(r => String(r.client_id || '').trim().toUpperCase() === cid);
if (!rec){
  return [{ json: { found: false, reason: 'unknown client', client_id: cid, doc } }];
}
const required = split(rec.required_docs);
const received = split(rec.received_docs);
const isRequired = required.map(lower).includes(lower(doc));
if (!isRequired){
  return [{ json: { found: false, reason: 'document not on the required list for this client', client_id: cid, client_name: rec.client_name, doc } }];
}
const newReceived = received.concat(received.map(lower).includes(lower(doc)) ? [] : [doc]);
const missing = required.filter(d => !newReceived.map(lower).includes(lower(d)));
return [{ json: {
  found: true, client_id: cid, client_name: String(rec.client_name || ''),
  email: String(rec.email || ''), doc, required_docs: rec.required_docs,
  new_received_docs: newReceived.join(', '),
  missing_after: missing, missing_after_text: missing.join(', '),
  all_complete: missing.length === 0
} }];
